window.VO = [{"id":"n01","text":"You're looking for the man with the mole. His cap is maroon.","at":0.24,"t0":0.12,"t1":3.255},{"id":"n02","text":"One of these three is him.","at":7.21,"t0":3.605,"t1":4.915},{"id":"n03","text":"Find the maroon cap.","at":10.53,"t0":5.265,"t1":6.545},{"id":"n04","text":"Can't? Neither could the witness.","at":17.09,"t0":8.545,"t1":10.27},{"id":"n05","text":"She swore all three caps were black.","at":21.04,"t0":10.52,"t1":12.445},{"id":"n06","text":"Then the stall switched its bulb on.","at":25.79,"t0":12.895,"t1":14.58},{"id":"n07c","text":"Number two. Maroon.","at":30.96,"t0":15.48,"t1":16.91},{"id":"n07d","text":"The whole time.","at":34.42,"t0":17.21,"t1":18.105},{"id":"n08","text":"If you picked him, you guessed.","at":36.91,"t0":18.455,"t1":19.975},{"id":"n09","text":"A cap doesn't glow. You only see the part of the light it throws back.","at":41.35,"t0":20.675,"t1":24.45},{"id":"n10","text":"That sign makes almost no red, so a maroon cap has nothing to throw back. It turns black.","at":49.6,"t0":24.8,"t1":30.59},{"id":"n11","text":"She wasn't lying. The sign was.","at":62.38,"t0":31.19,"t1":33.1}];
